/**
 * Original 3D geometry remaster for the existing Tournament minifigures.
 *
 * Reads authored-v2 GLBs generated by scripts/generate-core-fighters.mjs.
 * Extends the actual glTF meshes and joint hierarchies: no copyrighted models
 * or textures are downloaded. The original fighter rig is preserved.
 *
 * These are authored clean-room approximations, NOT AI-extracted or
 * frame-perfect recreations of television/cartoon assets.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const FIGHTERS = {
  'kai-tournament': { hood: true, type: 'ninja', gold: 0xd5a044, dark: 0x251c1c, cloth: 0x96151c, theme: 'fire', shoulder: true },
  'jay-tournament': { hood: true, type: 'ninja', gold: 0xc6a35e, dark: 0x24273b, cloth: 0x1553a6, theme: 'lightning' },
  'cole-tournament': { hood: true, type: 'ninja', gold: 0xd19143, dark: 0x121417, cloth: 0x2b2b2b, theme: 'earth', shoulder: true },
  'zane-techno': { hood: true, type: 'robot', gold: 0x98dff6, dark: 0x556a80, cloth: 0xd3d9db, theme: 'ice', shoulder: true },
  'zane-zx': { hood: true, type: 'robot', gold: 0xafc6ce, dark: 0x617078, cloth: 0xe1e6ea, theme: 'ice', shoulder: true },
  nya: { hood: false, type: 'samurai', gold: 0xd7a355, dark: 0x28232d, cloth: 0x8b2537, theme: 'water', shoulder: true },
  skylor: { hood: false, type: 'elemental', gold: 0xffc35e, dark: 0x6f3029, cloth: 0xba5c19, theme: 'amber' },
  'master-chen': { hood: false, type: 'master', gold: 0xd7b96d, dark: 0x4f252a, cloth: 0x752123, theme: 'staff', shoulder: true },
  'master-garmadon': { hood: false, type: 'master', gold: 0xcfc9b7, dark: 0x24232a, cloth: 0x323239, theme: 'creation', shoulder: true }
};
const TARGET = 'public/assets/models/fighters/variants';
const encoder = new TextEncoder();
const pad4 = (n) => (n + 3) & ~3;

export function parseGlb(raw) {
  if (raw.length < 20 || raw.readUInt32LE(0) !== 0x46546c67 ||
      raw.readUInt32LE(4) !== 2 || raw.readUInt32LE(8) !== raw.length) {
    throw new Error('Invalid GLB 2.0 header');
  }
  const jsonLength = raw.readUInt32LE(12);
  if (raw.readUInt32LE(16) !== 0x4e4f534a || jsonLength + 20 > raw.length) {
    throw new Error('Invalid GLB JSON chunk');
  }
  const gltf = JSON.parse(raw.subarray(20, 20 + jsonLength).toString('utf8').trim());
  const binaryStart = 20 + jsonLength;
  if (raw.readUInt32LE(binaryStart + 4) !== 0x004e4942) {
    throw new Error('Missing GLB binary chunk');
  }
  const binaryLength = raw.readUInt32LE(binaryStart);
  if (binaryStart + 8 + binaryLength !== raw.length) throw new Error('Incorrect binary chunk length');
  return { gltf, binary: raw.subarray(binaryStart + 8) };
}

export function encodeGlb(gltf, binary) {
  const json = encoder.encode(JSON.stringify(gltf));
  const jsonBytes = Buffer.alloc(pad4(json.length), 0x20);
  Buffer.from(json).copy(jsonBytes);
  const binBytes = Buffer.alloc(pad4(binary.length));
  Buffer.from(binary).copy(binBytes);
  const out = Buffer.alloc(12 + 8 + jsonBytes.length + 8 + binBytes.length);
  out.writeUInt32LE(0x46546c67, 0);
  out.writeUInt32LE(2, 4);
  out.writeUInt32LE(out.length, 8);
  out.writeUInt32LE(jsonBytes.length, 12);
  out.writeUInt32LE(0x4e4f534a, 16);
  jsonBytes.copy(out, 20);
  const off = 20 + jsonBytes.length;
  out.writeUInt32LE(binBytes.length, off);
  out.writeUInt32LE(0x004e4942, off + 4);
  binBytes.copy(out, off + 8);
  return out;
}

export function remaster(gltf, characterId) {
  const cfg = FIGHTERS[characterId];
  if (!cfg) throw new Error(`Unknown remaster fighter: ${characterId}`);
  const nodes = gltf.nodes;
  const meshes = gltf.meshes;
  const materials = gltf.materials;
  const source = new Map(meshes.map((mesh, index) => [mesh.name, index]));
  const originals = Object.fromEntries(['torso', 'head', 'leftArm', 'rightArm', 'leftLeg', 'rightLeg'].map((name) => {
    const index = nodes.findIndex((node) => node.name === name);
    if (index < 0) throw new Error(`Missing animation joint ${name} for ${characterId}`);
    return [name, index];
  }));

  const rgb = (hex) => [(hex >> 16 & 255) / 255, (hex >> 8 & 255) / 255, (hex & 255) / 255, 1];
  function mat(name, hex, metalness = 0.04) {
    materials.push({
      name,
      pbrMetallicRoughness: {
        baseColorFactor: rgb(hex), metallicFactor: metalness, roughnessFactor: metalness > 0.1 ? 0.3 : 0.37
      }
    });
    return materials.length - 1;
  }
  const palette = {
    cloth: mat('RemasterCloth', cfg.cloth),
    gold: mat('RemasterTrim', cfg.gold, 0.28),
    black: mat('RemasterDark', cfg.dark),
    eyes: mat('RemasterEyeGap', 0x151819),
    pale: mat('RemasterPale', cfg.type === 'robot' ? 0x9de2fa : 0xf4d054),
    silver: mat('RemasterSilver', cfg.type === 'robot' ? 0xc9dce5 : 0xc3bdb4, 0.55)
  };
  const meshCache = new Map();
  function meshWithColor(shape, color) {
    const key = `${shape}|${color}`;
    if (meshCache.has(key)) return meshCache.get(key);
    const basis = source.get(shape);
    if (basis === undefined) throw new Error(`Required source mesh ${shape} missing`);
    const original = meshes[basis];
    meshes.push({
      name: `Remaster_${shape}_${color}`,
      primitives: original.primitives.map((primitive) => ({ ...primitive, material: palette[color] }))
    });
    const newMesh = meshes.length - 1;
    meshCache.set(key, newMesh);
    return newMesh;
  }
  function create(parent, name, shape, color, position, scale, angle = 0) {
    const index = nodes.length;
    const item = { name, mesh: meshWithColor(shape, color), translation: position, scale };
    if (angle) item.rotation = [0, 0, Math.sin(angle / 2), Math.cos(angle / 2)];
    nodes.push(item);
    (nodes[parent].children ??= []).push(index);
    return index;
  }
  function box(parent, name, color, p, s, angle = 0) {
    return create(parent, name, 'PrimaryBox', color, p, s, angle);
  }
  function cyl(parent, name, color, p, s) {
    return create(parent, name, 'PrimaryCylinder', color, p, s);
  }
  function sphere(parent, name, color, p, s) {
    return create(parent, name, 'SkinSphere', color, p, s);
  }

  const torso = originals.torso;
  const head = originals.head;
  // Tournament crossover robes: layered lapels, belt, straps, breast plate,
  // pseudo-embroidery and a unique raised emblem with three dimensional ink.
  box(torso, 'remasterKimonoUnderlayer', 'black', [0, 0.04, 0.315], [0.48, 0.64, 0.025]);
  box(torso, 'remasterCollarLeft', 'gold', [-0.17, 0.32, 0.352], [0.085, 0.39, 0.036], -0.55);
  box(torso, 'remasterCollarRight', 'cloth', [0.17, 0.32, 0.355], [0.105, 0.42, 0.039], 0.55);
  box(torso, 'remasterDiagonalSash', 'gold', [0.05, 0.04, 0.363], [0.07, 0.66, 0.028], -0.67);
  box(torso, 'remasterOuterBorder', 'black', [-0.2, 0.03, 0.355], [0.045, 0.56, 0.025], 0.56);
  box(torso, 'remasterWaistWrap', 'black', [0, -0.35, 0.34], [0.82, 0.13, 0.055]);
  box(torso, 'remasterWaistGold', 'gold', [0, -0.42, 0.37], [0.76, 0.055, 0.037]);
  cyl(torso, 'remasterBeltKnot', 'gold', [-0.08, -0.42, 0.405], [0.083, 0.085, 0.043]);

  // Chest medallion: raised circular plate, stylized elemental zigzag.
  cyl(torso, 'remasterChestMedallion', 'gold', [-0.19, 0.16, 0.399], [0.115, 0.025, 0.115]);
  box(torso, 'remasterElementGlyph1', 'black', [-0.23, 0.19, 0.427], [0.045, 0.12, 0.021], -0.45);
  box(torso, 'remasterElementGlyph2', 'black', [-0.165, 0.135, 0.428], [0.04, 0.12, 0.02], 0.65);
  for (let i = 0; i < 4; i++) {
    box(torso, `remasterRobeStitch${i}`, 'gold', [0.2 + i * 0.03, 0.12 - i * 0.11, 0.389], [0.042, 0.018, 0.019], -0.15);
  }

  // Cloth masks are molded and layered around the facial eye gap. Remove
  // the V2 haircut and mouth meshes only on a masked costume.
  if (cfg.hood) {
    const oldHeadChildren = nodes[head].children ?? [];
    nodes[head].children = oldHeadChildren.filter((id) => !/^(?:hair|mouth|jaySideHair|kaiHeadband)/i.test(nodes[id].name));
    cyl(head, 'remasterHoodCrown', 'cloth', [0, 0.34, -0.025], [0.42, 0.22, 0.42]);
    box(head, 'remasterHoodForehead', 'cloth', [0, 0.21, 0.366], [0.73, 0.18, 0.105]);
    box(head, 'remasterEyeShadow', 'eyes', [0, 0.075, 0.372], [0.67, 0.21, 0.015]);
    box(head, 'remasterMaskLower', 'cloth', [0, -0.195, 0.375], [0.72, 0.35, 0.105]);
    box(head, 'remasterMaskNoseRidge', 'cloth', [0, -0.04, 0.44], [0.24, 0.14, 0.068]);
    box(head, 'remasterMaskFoldUpper', 'gold', [0, -0.104, 0.441], [0.47, 0.025, 0.025]);
    for (const side of [-1, 1]) {
      box(head, side < 0 ? 'remasterHoodLeftFold' : 'remasterHoodRightFold', 'cloth',
        [side * 0.35, -0.065, 0.11], [0.14, 0.65, 0.48]);
      box(head, side < 0 ? 'remasterEyeSideL' : 'remasterEyeSideR', 'gold',
        [side * 0.335, 0.067, 0.412], [0.034, 0.23, 0.032]);
      box(head, side < 0 ? 'remasterMaskFoldL' : 'remasterMaskFoldR', 'black',
        [side * 0.2, -0.24, 0.445], [0.22, 0.028, 0.025], side * 0.17);
    }
    cyl(head, 'remasterForeheadSeal', 'gold', [0, 0.235, 0.426], [0.08, 0.016, 0.08]);
    box(head, 'remasterForeheadGlyph', 'black', [0, 0.247, 0.445], [0.03, 0.07, 0.02]);
    if (cfg.type === 'robot') {
      box(head, 'remasterTechVisor', 'pale', [0, 0.095, 0.43], [0.44, 0.038, 0.025]);
      for (const side of [-1, 1]) {
        box(head, `remasterRobotCheek${side}`, 'silver', [side * 0.34, -0.2, 0.34], [0.07, 0.23, 0.13]);
      }
    }
  } else {
    box(head, 'remasterTempleBand', 'cloth', [0, 0.28, 0.32], [0.69, 0.075, 0.064]);
    cyl(head, 'remasterTempleInsignia', 'gold', [0, 0.275, 0.378], [0.08, 0.018, 0.08]);
    if (cfg.type === 'samurai') {
      box(head, 'remasterNyaFaceGuard', 'cloth', [0, -0.19, 0.379], [0.61, 0.23, 0.068]);
      box(head, 'remasterNyaSilverCheek', 'silver', [0, -0.1, 0.435], [0.31, 0.035, 0.02]);
    }
    if (cfg.type === 'master') {
      box(torso, 'remasterCeremonialPanel', 'gold', [0.2, -0.04, 0.404], [0.19, 0.49, 0.03]);
    }
  }

  if (cfg.shoulder) {
    for (const side of [-1, 1]) {
      const arm = originals[side < 0 ? 'leftArm' : 'rightArm'];
      box(arm, `remasterShoulderPlate${side}`, 'black', [side * 0.035, 0.018, 0.02], [0.34, 0.22, 0.54], side * 0.18);
      box(arm, `remasterShoulderEdge${side}`, 'gold', [side * 0.03, 0.135, 0.06], [0.27, 0.05, 0.57]);
      box(arm, `remasterWristEmblem${side}`, 'gold', [side * 0.035, -0.48, 0.14], [0.16, 0.075, 0.034]);
    }
  }

  for (const side of [-1, 1]) {
    const leg = originals[side < 0 ? 'leftLeg' : 'rightLeg'];
    box(leg, `remasterKneeWrap${side}`, 'black', [0, 0.08, 0.255], [0.28, 0.16, 0.06]);
    box(leg, `remasterKneeSeal${side}`, 'gold', [0, 0.08, 0.291], [0.07, 0.06, 0.015]);
    box(leg, `remasterBootTrim${side}`, 'gold', [0, -0.26, 0.32], [0.26, 0.03, 0.025]);
  }

  if (cfg.type === 'samurai') {
    // Scarlet shoulder guards and layered skirt, attached to actual torso joint.
    for (const side of [-1, 1]) {
      box(torso, `remasterSamuraiSkirt${side}`, 'cloth', [side * 0.27, -0.58, 0.14], [0.32, 0.29, 0.37], side * 0.12);
      box(torso, `remasterSamuraiSkirtTrim${side}`, 'gold', [side * 0.27, -0.72, 0.342], [0.28, 0.035, 0.026]);
    }
  }
  gltf.asset.generator = 'Tournament fighter rig remaster (original clean-room geometry)';
  gltf.asset.extras = { ...(gltf.asset.extras ?? {}), remaster: true, variant: characterId, riggedParts: Object.keys(originals), provenance: 'Procedural art, no extracted textures' };
  return gltf;
}

export async function buildAll({ root = resolve('.'), ids = Object.keys(FIGHTERS) } = {}) {
  const output = [];
  for (const id of ids) {
    const input = resolve(root, TARGET, id, 'authored-v2.glb');
    const target = resolve(root, TARGET, id, 'cartoon-remaster.glb');
    const source = parseGlb(await readFile(input));
    const gltf = remaster(source.gltf, id);
    const file = encodeGlb(gltf, source.binary);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, file);
    output.push({ id, target, bytes: file.length, nodes: gltf.nodes.length });
    console.log(`Remastered ${id}: ${gltf.nodes.length} nodes, ${file.length} bytes`);
  }
  return output;
}

if (process.argv[1] && import.meta.url === new URL(`file://${resolve(process.argv[1])}`).href) {
  buildAll().catch((error) => { console.error(error); process.exitCode = 1; });
}
